H.background();
const nN2 = Math.max(0, P.molN2);
const nH2 = Math.max(0, P.molH2);
const extN2 = nN2 / 1;
const extH2 = nH2 / 3;
const ext = Math.min(extN2, extH2);
const limiting = extN2 <= extH2 ? "N2" : "H2";
const usedN2 = ext * 1, usedH2 = ext * 3;
const leftN2 = nN2 - usedN2, leftH2 = nH2 - usedH2;
const prodNH3 = ext * 2;
H.text("Limiting reactant:  N2 + 3 H2 -> 2 NH3", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Whichever reactant gives the SMALLER reaction extent runs out first and caps the product.", 24, 52, { color: H.colors.sub, size: 13 });

const prog = 0.5 - 0.5 * Math.cos(t * 1.0);
const bx = 80, bw = 520, bh = 30;
const scaleMax = Math.max(nN2, nH2, prodNH3, 0.001);
function row(y, label, val, col) {
  H.rect(bx, y, bw, bh, { stroke: H.colors.grid, width: 1, radius: 6 });
  const w = bw * Math.min(1, val / scaleMax);
  H.rect(bx, y, Math.max(0, w), bh, { fill: col, radius: 6 });
  H.text(label, bx, y - 7, { color: H.colors.ink, size: 12, weight: 700 });
}
const curN2 = nN2 - usedN2 * prog;
const curH2 = nH2 - usedH2 * prog;
const curNH3 = prodNH3 * prog;
row(95, "N2 remaining = " + curN2.toFixed(2) + " mol", curN2, H.colors.accent);
row(150, "H2 remaining = " + curH2.toFixed(2) + " mol", curH2, H.colors.good);
row(205, "NH3 formed = " + curNH3.toFixed(2) + " mol", curNH3, H.colors.violet);

H.text("Limiting reactant: " + limiting, 24, 300, { color: H.colors.warn, size: 16, weight: 700 });
H.text("Reaction extent = " + ext.toFixed(3) + " mol rxn", 24, 326, { color: H.colors.sub, size: 13 });
H.text("Max NH3 = " + prodNH3.toFixed(3) + " mol", 24, 348, { color: H.colors.violet, size: 14, weight: 700 });
H.text("Excess left: N2 " + leftN2.toFixed(2) + " mol, H2 " + leftH2.toFixed(2) + " mol", 24, 372, { color: H.colors.sub, size: 13 });
H.legend([
  { label: "N2", color: H.colors.accent },
  { label: "H2", color: H.colors.good },
  { label: "NH3", color: H.colors.violet }
], 640, 100);
